// This file is generated by AI.

// 启动序列的最后一步: 什么时候把主窗口显示出来。
//
// 主窗口以 `visible: false` 创建 —— 启动时前端还要拉模块、装配 Monaco, 开发模式下这段时间可以
// 长达数秒。**窗口必须等这段做完再显示**, 否则用户看到的就是一段空白窗口。

import { getCurrentWindow } from '@tauri-apps/api/window';

/** 正常路径是否已经显示过窗口 (只用于让保险丝判断自己该不该兜底)。 */
let windowRevealed = false;

/**
 * 等首帧绘制完成。
 *
 * 连等两帧: 单个 `requestAnimationFrame` 回调可能在样式应用之前触发。
 *
 * **刻意不设超时**: 任何"到点就显示"的兜底都会抢在首帧之前把窗口放出来 —— 启动慢一点 (冷启动、
 * 开了调试器) 就又会看到空白窗口。这里只负责"等到真的画出来", 万一帧永远不来, 由
 * `armWindowRevealFailsafe` 兜底。
 */
export function afterFirstPaint(): Promise<void> {
  return new Promise((resolve) => {
    requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
  });
}

/** 显示窗口 (幂等)。失败不静默: 显示不出来等于用户什么都看不到。 */
async function showWindow(): Promise<void> {
  try {
    await getCurrentWindow().show();
    windowRevealed = true;
  } catch (error) {
    console.error('[boot] 显示主窗口失败', error);
  }
}

/** 首帧绘制完成后显示主窗口 —— 正常路径, 由 `+page.svelte` 的 `onMount` 调用。 */
export async function revealWindow(): Promise<void> {
  await afterFirstPaint();
  await showWindow();
}

/**
 * 保险丝: 正常路径没能显示窗口时兜底。
 *
 * 挂载过程中任何一步抛错, 都会让 `+page.svelte` 的 `onMount` 轮不到执行 —— 此时窗口一直是隐藏的,
 * 桌面上什么都没有, 而且控制台在窗口之外, 用户看不到任何报错。在 `+layout.svelte` 的脚本最前面挂上
 * 它 (早于任何可能抛错的初始化), 正常启动时它什么也不做。
 *
 * @param delayMs 必须明显大于正常启动耗时, 否则会抢在首帧之前把窗口显示出来
 */
export function armWindowRevealFailsafe(delayMs = 12_000): void {
  setTimeout(() => {
    if (windowRevealed) return;
    console.warn('[boot] 正常路径未能显示主窗口, 由保险丝兜底 —— 页面挂载大概率抛错了');
    void showWindow();
  }, delayMs);
}
